            ("<", _) => (BinaryOp::Lt, 3, 1),
            (">", _) => (BinaryOp::Gt, 3, 1),
            ("+", _) => (BinaryOp::Add, 4, 1),
            ("-", _) => (BinaryOp::Sub, 4, 1),
