    {
      "id": "W03",
      "classification": "SOURCE_DECLARATION",
      "profile": "Core1 specimen",
      "statement": "ConditionalReserve declares Core1 and allocate with approved/units/quotient/remainder inputs. It writes units == quotient * 3 + remainder, remainder <3, and a statement-position ensures rounds ==0 before financial effects and Next declarations.",
      "citations": [
        {
          "inputFile": "S11-conditional-reserve.mori",
          "sha256": "395e647534160fde45325232e5f1650a8bd48ce1455a68b28af203bf8bdbe357",
          "lineStart": 1,
          "lineEnd": 24,
          "literal": "language "moriarty/1";
agreement ConditionalReserve {
  state allocated: Bool = false;
  state rounds: UInt = 0;
  state marker: UInt = 77;
  asset A = { network: "oracle-unit", issuer: "reserve-issuer", reference: "A", scale: 0 };
  asset B = { network: "oracle-unit", issuer: "reserve-issuer", reference: "B", scale: 0 };
  action allocate(approved: Bool, units: UInt, quotient: UInt, remainder: UInt) {
    requires approved and not allocated;
    requires remainder < 3;
    requires units == quotient * 3 + remainder;
    requires units >= 3 and quotient not = 0;
    let toAlpha = quotient * 2;
    let toBeta = quotient;
    ensures rounds == 0;
    fee(A, "vault", "fees", 2);
    transfer(A, "vault", "alpha", toAlpha);
    transfer(A, "vault", "beta", toBeta);
    transfer(B, "vault", "alpha", 4);
    liability("allocation_reserve", A, "vault", "owner", remainder);
    liability("rebate", B, "vault", "owner", 6);
    next allocated = true;
    next rounds = rounds + 1;
    ensures liability_amount("allocation_reserve") == remainder;"
        },
        {
          "inputFile": "S13-reserve-allocate.selector.json",
          "sha256": "4110ae0ca7031482155ad362a787b5fd76c59492eb045a840ee58deafef9556a",
          "lineStart": 2,
          "lineEnd": 9,
          "literal": "  "format": "moriarty-k2-relation-selector/1",
  "language": "moriarty/1",
  "semantics": "moriarty-core/1",
  "action": "allocate",
  "adapter": "SettlementHashV2",
  "cap": "NotBound",
  "accounting": "GrossDebitAndFees",
  "frame": "TouchedOnly""
        }
      ]
